                doubleMxN A = new doubleMxN(dim, dim, Allocator.Temp);
                A[0, 0] = 2f; A[1, 1] = -3f; A[2, 2] = 0.5f; A[3, 3] = 4f;
                double logAbs = Analysis.logDeterminant(in A, out double sign);
